        for r in range(start, end + 1):
            seg_rightmost_list.append(max(c for c in range(cols) if grid[r][c] == fg))

        # Find mode (most frequent)
        from collections import Counter
        seg_rightmost_counts = Counter(seg_rightmost_list)
        mode_rightmost = seg_rightmost_counts.most_common(1)[0][0]

        # Apply transformation: fill bg cells after mode position
        for r in range(start, end + 1):
            rightmost = max(c for c in range(cols) if grid[r][c] == fg)
            if rightmost == mode_rightmost:
