# Implement the fixed transform
def transform_fixed(grid, fg, bg, w, h):
    result = [row[:] for row in grid]

    for start in range(h):
        row_has_fg = any(grid[start][c] == fg for c in range(w))
        if not row_has_fg:
            continue

        end = start
        while end + 1 < h and any(grid[end+1][c] == fg for c in range(w)):
            end += 1

        segment_rightmost = [(r, max(c for c in range(w) if grid[r][c] == fg)) for r in range(start, end+1)]
        max_rightmost = max(rp for _, rp in segment_rightmost)
        max_rows = [r for r, rp in segment_rightmost if rp == max_rightmost]

        for r in max_rows:
            for c in range(max_rightmost + 1, w):
                if result[r][c] == bg:
                    result[r][c] = 1

        start = end if end + 1 < h else end

    return result

