def transform_complete(grid, fg, bg, w, h):
    """
    Rule: For each connected component of rows with FG (vertical neighbors):
    - Find the row(s) with the maximum rightmost FG position
    - If background exists after that position, fill it with 1
    """
    result = [row[:] for row in grid]

    # Step 1: Label connected components
    component_row_map = {}
    for r in range(h):
        has_fg = any(grid[r][c] == fg for c in range(w))
        if not has_fg:
            component_row_map[r] = None
            continue
        component_row_map[r] = "processing"

    label = 0
    for r in range(h):
        has_fg = any(grid[r][c] == fg for c in range(w))
        if not has_fg:
            continue
        if component_row_map[r] == "processing":
            label += 1
            component_row_map[r] = label
            if r + 1 < h and any(grid[r+1][c] == fg for c in range(w)):
                # Check that row r+1 has FG first
                row_r1_has_fg = any(grid[r+1][c] == fg for c in range(w))
                if row_r1_has_fg:
                    component_row_map[r+1] = label

    # Reset components for rows not visited
    for r in range(h):
        if component_row_map[r] not in [label, None]:
            component_row_map[r] = None

    # Step 2: Transform each component
    for label in range(1, label + 1):
        rows = [r for r in range(h) if component_row_map[r] == label]

        # Find max rightmost
        segment_rightmost = [(r, max(c for c in range(w) if grid[r][c] == fg)) for r in rows]
        max_rightmost = max(rp for _, rp in segment_rightmost)
        max_rows = [r for r, rp in segment_rightmost if rp == max_rightmost]

        # Transform if bg exists after max_rightmost
        for r in max_rows:
            for c in range(max_rightmost + 1, w):
                if result[r][c] == bg:
                    result[r][c] = 1

